// 날짜/시간 문자열을 YY-MM-DD HH:MM 포맷으로 변환하는 헬퍼 함수
const formatShortDateTime = (datetimeStr) => {
  if (!datetimeStr) return '-';
  const cleanStr = datetimeStr.replace(' ', 'T');
  const [datePart, timePart] = cleanStr.split('T');
  if (!datePart) return '-';

  const dateComponents = datePart.split('-');
  if (dateComponents.length !== 3) return datetimeStr;

  const yy = dateComponents[0].slice(-2); // 2026 -> 26
  const mm = dateComponents[1];
  const dd = dateComponents[2];
  const time = timePart ? timePart.slice(0, 5) : '00:00';

  return `${yy}-${mm}-${dd} ${time}`;
};

// 15분 단위 픽업 시간 파싱 함수
const parseTimeToParts = (timeStr) => {
  if (!timeStr) return { ampm: "오후", hour: "02", minute: "00" };
  const [hStr, mStr] = timeStr.split(':');
  let h = parseInt(hStr, 10);
  let m = parseInt(mStr, 10);

  m = Math.round(m / 15) * 15;
  if (m === 60) {
    m = 0;
    h = (h + 1) % 24;
  }

  const ampm = h >= 12 ? "오후" : "오전";
  let h12 = h % 12;
  if (h12 === 0) h12 = 12;

  return {
    ampm,
    hour: String(h12).padStart(2, '0'),
    minute: String(m).padStart(2, '0')
  };
};

const formatPartsToTime = (ampm, hour, minute) => {
  let h = parseInt(hour, 10);
  if (ampm === "오후" && h < 12) h += 12;
  if (ampm === "오전" && h === 12) h = 0;
  return `${String(h).padStart(2, '0')}:${minute}`;
};

// KST 실시간 일시 구하기
const getKoreaNowFormatted = () => {
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const kst = new Date(utc + (9 * 60 * 60 * 1000));

  const year = kst.getFullYear();
  const month = String(kst.getMonth() + 1).padStart(2, '0');
  const day = String(kst.getDate()).padStart(2, '0');
  const dateStr = `${year}-${month}-${day}`;

  const hours = String(kst.getHours()).padStart(2, '0');
  const minutes = String(kst.getMinutes()).padStart(2, '0');
  const timeStr = `${hours}:${minutes}`;

  const dayOfWeek = kst.getDay(); // 0:일, 1:월, ...
  const currentHour = kst.getHours();

  return { date: dateStr, time: timeStr, dayOfWeek, currentHour, kstDateObj: kst };
};

// 현재 시간 직후의 가장 가까운 30분 단위 픽업 일시 계산 함수
const getNextQuarterHourDateTime = () => {
  const now = new Date();
  const utc = now.getTime() + (now.getTimezoneOffset() * 60000);
  const kst = new Date(utc + (9 * 60 * 60 * 1000));

  const totalMinutes = kst.getHours() * 60 + kst.getMinutes() + 1;
  const remainder = totalMinutes % 30;
  const roundedMinutes = totalMinutes + (30 - remainder);

  const targetDate = new Date(kst.getTime());
  targetDate.setHours(Math.floor(roundedMinutes / 60), roundedMinutes % 60, 0, 0);

  const year = targetDate.getFullYear();
  const month = String(targetDate.getMonth() + 1).padStart(2, '0');
  const day = String(targetDate.getDate()).padStart(2, '0');
  const dateStr = `${year}-${month}-${day}`;

  const hours = String(targetDate.getHours()).padStart(2, '0');
  const minutes = String(targetDate.getMinutes()).padStart(2, '0');
  const timeStr = `${hours}:${minutes}`;

  return { date: dateStr, time: timeStr };
};

// CSV 변환 헬퍼 (배열 -> CSV 파일 다운로드)
const downloadCSV = (headers, rows, filename) => {
  const escapeCSV = (val) => {
    if (val === null || val === undefined) return '""';
    const str = String(val).replace(/"/g, '""');
    return `"${str}"`;
  };

  const csvContent = [
    headers.map(escapeCSV).join(','),
    ...rows.map(row => row.map(escapeCSV).join(','))
  ].join('\r\n');

  const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', filename);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

// CSV 텍스트 파싱 헬퍼
const parseCSVText = (text) => {
  const lines = text.split(/\r\n|\n/);
  const result = [];

  for (let line of lines) {
    line = line.trim();
    if (!line) continue;

    const row = [];
    let insideQuote = false;
    let entry = '';

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (insideQuote && line[i + 1] === '"') {
          entry += '"';
          i++;
        } else {
          insideQuote = !insideQuote;
        }
      } else if (char === ',' && !insideQuote) {
        row.push(entry.trim());
        entry = '';
      } else {
        entry += char;
      }
    }
    row.push(entry.trim());
    result.push(row);
  }

  if (result.length < 2) return [];
  const headers = result[0].map(h => h.replace(/^"|"$/g, ''));
  const rows = result.slice(1);

  return rows.map(r => {
    const obj = {};
    headers.forEach((h, idx) => {
      let val = r[idx] || '';
      if (val.startsWith('"') && val.endsWith('"')) {
        val = val.slice(1, -1).replace(/""/g, '"');
      }
      obj[h] = val;
    });
    return obj;
  });
};

